// Fills the confirmation email template (ported unchanged from draft_order.php).
// Template HTML lives in email-template-html.js, generated by scripts/port-email-template.js.
import {
  EMAIL_BODY_TEMPLATE,
  LINE_ITEM_ROW_TEMPLATE,
  PROPERTY_LINE_TEMPLATE,
} from './email-template-html.js';

const EMAIL_SUBJECT = 'Thank you for placing your order!';
const STOREFRONT_URL = 'https://roofvents.com';

function escapeHtml(unsafeText) {
  return String(unsafeText ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/** Same output as PHP number_format($amount, 2), e.g. 1234.5 → "1,234.50". The "$" is in the template. */
function formatMoney(amount) {
  return Number(amount).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

/** Same output as PHP format('F j, Y'), e.g. "November 11, 2026". */
function formatOrderDate(isoDate) {
  return new Intl.DateTimeFormat('en-US', {
    month: 'long',
    day: 'numeric',
    year: 'numeric',
    timeZone: process.env.STORE_TIMEZONE || 'America/New_York',
  }).format(new Date(isoDate));
}

/** Replaces {{placeholder}}s in one pass (inserted values are never re-scanned). */
function fillTemplate(template, placeholderValues) {
  return template.replace(/\{\{(\w+)\}\}/g, (placeholder, placeholderName) => {
    if (!(placeholderName in placeholderValues)) throw new Error(`No value for ${placeholder}`);
    return placeholderValues[placeholderName];
  });
}

function getProductUrl(lineItem) {
  if (lineItem.product?.onlineStoreUrl) return lineItem.product.onlineStoreUrl;
  if (lineItem.product?.handle) return `${STOREFRONT_URL}/products/${lineItem.product.handle}`;
  return STOREFRONT_URL;
}

function buildLineItemRow(lineItem) {
  const unitPrice = Number(lineItem.originalUnitPriceSet.shopMoney.amount);

  const propertyLines = lineItem.customAttributes
    .filter((attribute) => !attribute.key.startsWith('_'))
    .map((attribute) => fillTemplate(PROPERTY_LINE_TEMPLATE, {
      name: escapeHtml(attribute.key),
      value: escapeHtml(attribute.value),
    }))
    .join('');

  return fillTemplate(LINE_ITEM_ROW_TEMPLATE, {
    product_url: escapeHtml(getProductUrl(lineItem)),
    image_url: escapeHtml(lineItem.image?.url ?? ''),
    title: escapeHtml(lineItem.name),
    properties: propertyLines,
    quantity: String(lineItem.quantity),
    unit_price: formatMoney(unitPrice),
    line_total: formatMoney(unitPrice * lineItem.quantity),
  });
}

/** Returns { subject, html } for the customer confirmation email. */
export function buildEmail({ draftOrder, firstName }) {
  const html = fillTemplate(EMAIL_BODY_TEMPLATE, {
    draft_name: escapeHtml(draftOrder.name),
    first_name: escapeHtml(firstName),
    created_at: formatOrderDate(draftOrder.createdAt),
    product_list: draftOrder.lineItems.nodes.map(buildLineItemRow).join(''),
    subtotal_price: formatMoney(draftOrder.subtotalPriceSet.shopMoney.amount),
    year: String(new Date().getFullYear()),
  });

  return { subject: EMAIL_SUBJECT, html };
}
